// Generated by `npm run studio -- seed-content` from studio/scripts/uae.wps.map.ack-correlation.v1.ts. Edit the source and seed again; never edit this file.
// The correlation map of the WPS acknowledgement (uae.wps.map.ack-correlation.v1, release 1.0.0; Issue I-267, R-09-212).
//
// The front door runs it on an ACK or NAK it receives, before the file is kept: it gives the key of the salary file the answer is
// for, the stem the sent file was recorded by (fileStem). As the source reads it (WpsAckNakFile): the AHR record's processed file
// name when the file carries one, else the answer's own name split from the back, the stem before the Central Bank's twelve-character
// file id. The naming is the source's reading of the SSM and provisional, as the scheme is. The runtime's native code-behind reads
// the same (R-08-16).

const FILE_ID_LENGTH = 12;

function stem(name: string): string {
  const base = name.split(/[\\/]/).pop() ?? '';
  const dot = base.indexOf('.');
  return dot > 0 ? base.slice(0, dot) : base;
}

export async function run({ ctx }) {
  const inbound = ctx.messages?.inbound;
  const text: string = inbound?.payload ?? '';
  const ahr = text.split(/\r?\n/).map((l) => l.trim()).find((l) => /^AHR,/i.test(l));
  // AHR,<ACCEPTED|REJECTED>,<processed file name>: the file it answers, when the answer says so (the name may hold commas).
  const processed = ahr?.split(',').slice(2).join(',').trim();
  let key = processed ? stem(processed) : '';
  if (!key) {
    const own = String(inbound?.fileName ?? '').split(/[\\/]/).pop() ?? '';
    const dot = own.lastIndexOf('.');
    const base = dot > 0 ? own.slice(0, dot) : own;
    if (base.length > FILE_ID_LENGTH) key = stem(base.slice(0, base.length - FILE_ID_LENGTH));
  }
  if (!key) return { outcome: 'uncorrelated', reasonCode: 'FF01' };
  ctx.messages = { ...(ctx.messages ?? {}), correlation: { fileStem: key } };
  return 'correlated';
}
